<?php
declare(strict_types=1);

/**
 * Phase 7c (Restaurant) end-to-end test: Restaurant templates 02–10 generated by tools/template-factory.
 *
 *   php tests/phase7c_restaurant_test.php <builder-url> <email> <password> <website-ids> <db-dsn> [export-website-id]
 *
 * <website-ids> is a comma-separated list of nine freshly generated websites, one per template, in order
 * restaurant_template_02 … restaurant_template_10. <db-dsn> is "dsn|user|password" for the builder database.
 */

require __DIR__ . '/support.php';

/** A form on a page: token, back-slug and absolute action URL. */
function formOn(Client $site, string $host, string $path, string $form): array
{
    $html = $site->req('GET', $path, [], false)['body'];
    preg_match('/<form class="[a-z]+-form" method="post" action="([^"]*\/form\/' . preg_quote($form, '/') . ')"/', $html, $act);
    preg_match('/name="_t" value="([^"]+)"/', $html, $t);
    preg_match('/name="_back" value="([^"]*)"/', $html, $b);
    return ['html' => $html, 'action' => isset($act[1]) ? $host . html_entity_decode($act[1]) : '', 't' => $t[1] ?? '', 'back' => $b[1] ?? ''];
}

[$_, $base, $email, $password, $ids, $dsn, $exportId] = $argv + [null, 'http://127.0.0.1:8080', 'info@channelsoftech.com', '', '', '', '0'];
$base = rtrim((string) $base, '/');
$ids = array_map('intval', array_filter(explode(',', (string) $ids)));
$sfx = substr(bin2hex(random_bytes(3)), 0, 6);
$pass = $fail = 0;
$started = microtime(true);
$root = dirname(__DIR__);

// Expected design per template: prefix, hero/header/footer variants and a phrase from the demo copy.
$expect = [
    '02' => ['mrc', 'split', 'pill', 'centered', 'cards', 'band', 'cards', 'Slow mornings start here'],
    '03' => ['atr', 'panel', 'bar', 'band', 'board', 'panel', 'list', 'Crisp dosas, soft idlis, strong filter coffee'],
    '04' => ['fnl', 'cover', 'dark', 'columns', 'cards', 'band', 'cards', 'Pizza the slow way'],
    '05' => ['eao', 'editorial', 'center', 'centered', 'board', 'panel', 'list', 'Twelve courses. One fire. Your evening.'],
    '06' => ['ltw', 'stack', 'pill', 'centered', 'cards', 'band', 'cards', 'Asia, one small plate at a time'],
    '07' => ['bnb', 'split', 'center', 'band', 'cards', 'panel', 'cards', 'Life is short. Eat the pastry.'],
    '08' => ['kkc', 'panel', 'dark', 'columns', 'board', 'band', 'list', 'From the boat to your banana leaf'],
    '09' => ['sks', 'cover', 'pill', 'centered', 'cards', 'panel', 'cards', 'Sunsets, smoke and good company'],
    '10' => ['pdd', 'editorial', 'bar', 'band', 'board', 'panel', 'list', 'Punjab da swaad, dil se'],
];
$known = ['mrd', 'kst', 'hzt', 'sfr', 'lvh', 'skl', 'ldg', 'crl', 'lyc', 'trm', 'nbf', 'vtx', 'gfh', 'icw', 'bpt', 'scr', 'cmc', 'hbc', 'pls', 'lac', 'apx', 'mit', 'cis', 'cfa', 'rsp', 'wsm', 'lgb', 'pcr', 'srh', 'scd', 'cse', 'lhc', 'psd', 'rvp', 'vga', 'mnw', 'chi', 'kth', 'vlt', 'gbo', 'dwp', 'aur', 'ttt', 'erc', 'stz', 'ppl', 'cvl', 'nvk', 'mrs', 'bhl', 'hhv', 'bwr', 'gft', 'hcr', 'hhr', 'ccm', 'smt', 'yst', 'wwg', 'jts', 'rrj', 'hwn', 'ihp', 'cpt'];

[$d, $du, $dp] = explode('|', (string) $dsn) + ['', '', ''];
$pdo = new PDO($d, $du, $dp, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);

echo "\n== Template files ==\n";
$prefixes = [];
$descriptions = [];
$designs = [];
foreach ($expect as $n => [$p, $hero, $header, $footer, $menu, $hours, $events]) {
    $dir = "$root/templates/restaurant/restaurant_template_$n";
    $m = json_decode((string) @file_get_contents("$dir/manifest.json"), true) ?: [];
    $css = (string) @file_get_contents("$dir/assets/css/style.css");
    $layout = (string) @file_get_contents("$dir/layouts/default.php");
    $prefixes[] = $p;
    $descriptions[] = $m['description'] ?? '';
    $designs[] = "$hero/$header/$footer/$menu/" . ($m['theme']['defaults']['heading_font'] ?? '') . '/' . ($m['theme']['defaults']['primary'] ?? '');

    $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
    $leftover = [];
    $foreign = [];
    foreach ($files as $f) {
        if (!preg_match('/\.(php|css|js|json)$/', $f->getFilename())) {
            continue;
        }
        $txt = (string) file_get_contents($f->getPathname());
        if (str_contains($txt, '{{')) {
            $leftover[] = $f->getFilename();
        }
        foreach ($known as $k) {
            if (preg_match('/(?<![a-z-])' . $k . '-[a-z]/', $txt)) {
                $foreign[] = $f->getFilename() . ":$k";
            }
        }
    }
    check("$n manifest: id, name, category, version, unique description", ($m['id'] ?? '') === "restaurant_template_$n" && ($m['category'] ?? '') === 'restaurant' && preg_match('/^\d+\.\d+\.\d+$/', (string) ($m['version'] ?? '')) === 1 && strlen((string) ($m['description'] ?? '')) > 80);
    check("$n uses its own prefix \"$p\" throughout; no placeholders or other templates' classes left", str_contains($layout, "<body class=\"$p ") && !$leftover && !$foreign && preg_match_all("/\\.$p-[a-z]/", $css) > 200, json_encode([$leftover, $foreign]));
    check("$n stylesheet is theme-driven (no hard-coded brand colours)", !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['primary'] ?? '#'))) && !str_contains(strtoupper($css), strtoupper((string) ($m['theme']['defaults']['secondary'] ?? '#'))) && str_contains($css, 'var(--wb-primary)'));
    $demo = json_decode((string) @file_get_contents("$dir/demo.json"), true) ?: [];
    preg_match_all('#theme:images/([a-z0-9._-]+)#', json_encode($demo, JSON_UNESCAPED_SLASHES), $im);
    $missing = array_filter(array_unique($im[1]), static fn ($f) => !is_file("$dir/assets/images/$f"));
    $dishes = [];
    foreach ($demo['pages'] ?? [] as $pg) {
        foreach ($pg['sections'] as $s) {
            if ($s['type'] === 'menu') {
                $dishes = array_merge($dishes, $s['data']['items']);
            }
        }
    }
    $badDish = array_filter($dishes, static fn ($d) => !in_array($d['diet'], ['', 'veg', 'nonveg', 'egg', 'vegan'], true) || !in_array($d['spice'], ['0', '1', '2', '3'], true) || ($d['price'] ?? '') === '' || ($d['image'] ?? '') === '');
    check("$n demo images all exist (" . count(array_unique($im[1])) . " referenced), chef portraits, dish photos, preview.jpg present", !$missing && count(array_unique($im[1])) >= 20 && is_file("$dir/assets/images/chef-3.svg") && is_file("$dir/assets/images/hero.svg") && is_file("$dir/preview.jpg"), json_encode(array_values($missing)));
    check("$n demo menu: " . count($dishes) . ' dishes with valid diet marks, spice levels, prices and photos; home shows six signatures', count($dishes) >= 14 && !$badDish && count(array_values(array_filter($demo['pages']['']['sections'], static fn ($s) => $s['type'] === 'menu'))[0]['data']['items']) === 6, json_encode(array_column($badDish, 'name')));
    check("$n has its \"$menu\" menu, \"$hours\" opening hours and \"$events\" events views and the menu tabs script", str_contains((string) file_get_contents("$dir/sections/menu.php"), "$p-menu-$menu") && str_contains((string) file_get_contents("$dir/sections/opening_hours.php"), "$p-hours-$hours")
        && str_contains((string) file_get_contents("$dir/assets/js/main.js"), "data-$p-menu") && is_file("$dir/sections/booking_form.php") && is_file("$dir/sections/events.php"));
    $pt = $m['page_types'] ?? [];
    $homeTypes = array_column($demo['pages']['']['sections'] ?? [], 'type');
    check("$n home page type matches its demo; all section types have a view", ($pt['home']['default_sections'] ?? null) === $homeTypes && !array_filter($m['section_types'] ?? [], static fn ($t) => !is_file("$dir/sections/$t.php")));
}
check('Nine distinct prefixes, none shared with existing templates', count(array_unique($prefixes)) === 9 && !array_intersect($prefixes, $known));
check('Nine distinct descriptions and design combinations', count(array_unique($descriptions)) === 9 && count(array_unique($designs)) === 9);

$b = new Client($base);
check('Builder login', ($b->login($email, $password)['json']['ok'] ?? false) === true);
$rows = $pdo->query("SELECT t.code, t.status, c.slug FROM wb_templates t JOIN wb_categories c ON c.id = t.category_id WHERE t.code LIKE 'restaurant_template_%'")->fetchAll();
$byCode = array_column($rows, null, 'code');
$okReg = true;
foreach (array_keys($expect) as $n) {
    $okReg = $okReg && ($byCode["restaurant_template_$n"]['status'] ?? '') === 'active' && ($byCode["restaurant_template_$n"]['slug'] ?? '') === 'restaurant';
}
check('All nine registered and active in the Restaurant category', $okReg, json_encode($byCode));
spl_autoload_register(static function (string $class) use ($root): void {
    if (str_starts_with($class, 'App\\') && is_file($f = $root . '/app/' . str_replace('\\', '/', substr($class, 4)) . '.php')) {
        require $f;
    }
});
$cats = $pdo->query('SELECT slug FROM wb_categories')->fetchAll(PDO::FETCH_COLUMN);
$report = [];
foreach (array_keys($expect) as $n) {
    $v = (new App\Modules\Templates\ManifestValidator())->validate("$root/templates/restaurant/restaurant_template_$n", $cats, "restaurant_template_$n", 'restaurant');
    if ($v->errors() || $v->warnings()) {
        $report[$n] = [$v->errors(), $v->warnings()];
    }
}
check('Template validator: no errors or warnings for any of the nine', !$report, json_encode($report));

preg_match('/font-monospace" value="([A-Za-z0-9]+)"/', $b->req('GET', 'settings', [], false)['body'], $mm);
$qa = 'qa:' . ($mm[1] ?? '');

echo "\n== Generated sites ==\n";
$n = 2;
foreach ($ids as $wid) {
    $key = sprintf('%02d', $n++);
    [$p, $hero, $header, $footer, $menu, $hours, $events, $phrase] = $expect[$key];
    $demo = json_decode((string) file_get_contents("$root/templates/restaurant/restaurant_template_$key/demo.json"), true);
    $tp = (string) $pdo->query('SELECT table_prefix FROM wb_websites WHERE id = ' . $wid)->fetchColumn();
    $pdo->exec("DELETE FROM {$tp}login_attempts WHERE ip IN ('127.0.0.1', '::1')");
    $pdo->exec("UPDATE {$tp}contact_submissions SET created_at = created_at - INTERVAL 2 HOUR WHERE ip IN ('127.0.0.1', '::1')");
    $r = $b->req('POST', "websites/$wid/admin-account", ['email' => "rs{$key}owner$sfx@example.com", 'name' => 'Owner']);
    $siteUrl = substr(rtrim((string) ($r['json']['url'] ?? ''), '/'), 0, -strlen('admin'));
    $host = (string) preg_replace('#^(https?://[^/]+).*$#', '$1', $siteUrl);
    $pub = new Client($siteUrl);
    $pub->basic = $qa;
    $sec = static function (string $slug, string $type) use ($demo): array {
        foreach ($demo['pages'][$slug]['sections'] as $s) {
            if ($s['type'] === $type) {
                return $s['data'];
            }
        }
        return [];
    };

    $home = $pub->req('GET', '', [], false);
    $h = $home['body'];
    check("$key home 200 with body class \"$p\", $header header, $hero hero, $footer footer", $home['code'] === 200 && str_contains($h, "<body class=\"$p $p-mood-") && str_contains($h, "$p-header-$header") && str_contains($h, "$p-hero-$hero") && str_contains($h, "$p-footer-$footer"));
    check("$key hero copy with reserve and menu buttons; menu has Menu, Events and Reservations; legal links", str_contains($h, htmlspecialchars($phrase, ENT_QUOTES)) && preg_match('#href="[^"]*/reservations"#', $h) === 1 && preg_match('#href="[^"]*/menu"#', $h) === 1
        && preg_match('#href="[^"]*/events"#', $h) === 1 && str_contains($h, 'privacy-policy') && str_contains($h, 'terms-and-conditions'));
    $sig = $sec('', 'menu')['items'];
    check("$key home signature menu: six dishes in the $menu view with diet marks, prices and photos, listed (no tabs)", str_contains($h, "$p-menu-$menu") && substr_count($h, $menu === 'board' ? "class=\"$p-dish" . '"' : "class=\"$p-dish-card ") + substr_count($h, "class=\"$p-dish has-img\"") === 6
        && str_contains($h, "$p-diet is-") && str_contains($h, htmlspecialchars($sig[0]['price'], ENT_QUOTES)) && !str_contains($h, "data-$p-menu") && str_contains($h, "$p-menu-legend"));
    check("$key home: about, features, gallery, testimonials, booking form (guests, time, date) and CTA", str_contains($h, "$p-about") && str_contains($h, "$p-gallery") && str_contains($h, "$p-quote") && str_contains($h, "$p-booking")
        && str_contains($h, 'name="extra[Guests]"') && str_contains($h, 'name="extra[Time]"') && str_contains($h, 'name="extra[Date]"') && str_contains($h, "$p-cta"));
    preg_match_all('#src="([^"]+/theme/assets/images/[^"?]+)#', $h, $srcs);
    $bad = 0;
    foreach (array_slice(array_unique($srcs[1]), 0, 8) as $src) {
        $bad += $pub->req('GET', $host . html_entity_decode($src), [], false)['code'] === 200 ? 0 : 1;
    }
    check("$key theme images served", count(array_unique($srcs[1])) >= 10 && $bad === 0);

    $full = $sec('menu', 'menu')['items'];
    $courses = array_values(array_unique(array_column($full, 'course')));
    $mp = $pub->req('GET', 'menu', [], false)['body'];
    check("$key menu page: " . count($full) . ' dishes in ' . count($courses) . ' course tabs (' . implode(', ', $courses) . '), key and note', substr_count($mp, 'role="tab"') === count($courses) && substr_count($mp, 'role="tabpanel"') === count($courses) && str_contains($mp, "data-$p-menu")
        && substr_count($mp, htmlspecialchars($full[count($full) - 1]['name'], ENT_QUOTES)) >= 1 && str_contains($mp, 'Prices include taxes') && str_contains($mp, "$p-banner"));
    $spicy = count(array_filter($full, static fn ($d) => $d['spice'] !== '0'));
    check("$key menu marks: diet marks for every dish with a diet, $spicy spice ratings, labels", substr_count($mp, "class=\"$p-diet is-") >= count(array_filter($full, static fn ($d) => $d['diet'] !== '')) && substr_count($mp, "class=\"$p-spice\"") === $spicy && str_contains($mp, "$p-dish-tag"));

    $ev = $pub->req('GET', 'events', [], false)['body'];
    $evs = $sec('events', 'events')['items'];
    check("$key events page: hosting options and " . count($evs) . " upcoming events in the $events view, in date order", str_contains($ev, "$p-events-$events") && str_contains($ev, htmlspecialchars($evs[0]['title'], ENT_QUOTES)) && str_contains($ev, "$p-services")
        && strpos($ev, htmlspecialchars($evs[0]['title'], ENT_QUOTES)) < strpos($ev, htmlspecialchars($evs[count($evs) - 1]['title'], ENT_QUOTES)));
    $res = $pub->req('GET', 'reservations', [], false)['body'];
    $oh = $sec('reservations', 'opening_hours');
    check("$key reservations: booking form, $hours opening hours with call highlight, FAQ", str_contains($res, 'Table booking') && str_contains($res, "$p-hours-$hours") && str_contains($res, htmlspecialchars($oh['rows'][0]['label'], ENT_QUOTES))
        && str_contains($res, 'href="tel:' . str_replace(' ', '', $oh['highlight_value'])) && str_contains($res, "$p-faq"));
    $pagesOk = true;
    foreach (['about' => "$p-member", 'contact' => "$p-form", 'privacy-policy' => "$p-rich", 'terms-and-conditions' => "$p-rich"] as $slug => $marker) {
        $pg = $pub->req('GET', $slug, [], false);
        $pagesOk = $pagesOk && $pg['code'] === 200 && str_contains($pg['body'], $marker) && str_contains($pg['body'], "$p-banner") && str_contains($pg['body'], "$p-crumbs");
    }
    check("$key about (chefs, press), contact and legal pages with banner and breadcrumbs", $pagesOk);
    $nf = $pub->req('GET', 'no-such-page-' . $sfx, [], false);
    check("$key 404 page uses the template", $nf['code'] === 404 && str_contains($nf['body'], "$p-404"));

    $bf = $sec('reservations', 'booking_form');
    $guests = preg_split('/\R/', $bf['select1_options'])[1];
    $time = preg_split('/\R/', $bf['select2_options'])[2];
    $f = formOn($pub, $host, 'reservations', 'booking');
    sleep(3);
    $date = date('Y-m-d', strtotime('+4 days'));
    $r = $pub->req('POST', $f['action'], ['_t' => $f['t'], '_back' => $f['back'], 'name' => "Diner $key $sfx", 'phone' => '+91 98200 55555', 'message' => 'Window table please', 'extra' => ['Guests' => $guests, 'Time' => $time, 'Date' => $date]], false);
    $row = $pdo->query("SELECT form_key, extra_json FROM {$tp}contact_submissions WHERE name = " . $pdo->quote("Diner $key $sfx"))->fetch();
    check("$key table booking ($guests guests, $time) stored as a booking; the section's thank-you is shown", $f['action'] !== '' && str_contains((string) $r['location'], 'status=sent') && $row && $row['form_key'] === 'booking'
        && json_decode($row['extra_json'], true) === ['Guests' => $guests, 'Time' => $time, 'Date' => $date] && str_contains($pub->req('GET', $r['location'], [], false)['body'], htmlspecialchars($bf['success_message'], ENT_QUOTES)), json_encode($row));

    $pdo->exec("UPDATE {$tp}contact_submissions SET created_at = created_at - INTERVAL 2 HOUR WHERE ip IN ('127.0.0.1', '::1')");
    $f = formOn($pub, $host, 'contact', 'contact');
    sleep(3);
    $post = $pub->req('POST', $f['action'], ['_t' => $f['t'], '_back' => $f['back'], 'name' => "Client $key $sfx", 'email' => "c$key$sfx@example.com", 'phone' => '+91 98450 22222', 'subject' => 'Catering', 'message' => "Question about template $key."], false);
    $after = $pub->req('GET', (string) $post['location'], [], false)['body'];
    $saved = (int) $pdo->query("SELECT COUNT(*) FROM {$tp}contact_submissions WHERE name = " . $pdo->quote("Client $key $sfx"))->fetchColumn();
    check("$key contact form submits, shows the success message and stores the enquiry", $f['action'] !== '' && str_contains($after, "$p-form-alert is-sent") && $saved === 1);
}
check('Nine websites tested', count($ids) === 9);

if ((int) $exportId > 0) {
    echo "\n== Export ==\n";
    $r = $b->req('POST', "websites/$exportId/exports", ['type' => 'full', 'prefix' => 'site_']);
    $eid = $r['json']['state']['export_id'] ?? 0;
    $st = ['status' => 'running'];
    for ($i = 0; $i < 20 && ($st['status'] ?? '') === 'running'; $i++) {
        $st = $b->req('POST', "websites/$exportId/exports/$eid/step")['json']['state'] ?? ['status' => 'error'];
    }
    check('Full export of a factory-built site completes', ($st['status'] ?? '') === 'done', json_encode($st));
    $zip = $b->req('GET', "websites/$exportId/exports/$eid/download", [], false);
    $tmp = tempnam(sys_get_temp_dir(), 'z7rs');
    file_put_contents($tmp, $zip['body']);
    $za = new ZipArchive();
    $names = [];
    if ($za->open($tmp) === true) {
        for ($i = 0; $i < $za->numFiles; $i++) {
            $names[] = $za->getNameIndex($i);
        }
        $za->close();
    }
    unlink($tmp);
    $flat = implode("\n", $names);
    check('Export contains the template (layout, stylesheet, dish photos, menu view, tabs script)', str_contains($flat, 'layouts/default.php') && str_contains($flat, 'assets/css/style.css') && str_contains($flat, 'assets/images/hero.svg') && preg_match('#assets/images/dish-[a-z_]+\\.svg#', $flat) === 1 && str_contains($flat, 'sections/menu.php') && str_contains($flat, 'assets/js/main.js'));
    check('Export contains no factory tooling', !str_contains($flat, 'template-factory') && !preg_match('/\.py$/m', $flat));
}

printf("\n%d passed, %d failed (%.1fs)\n", $pass, $fail, microtime(true) - $started);
exit($fail ? 1 : 0);
